System.Collections.IEnumerator Check(){
 var c=UnityEngine.Camera.main; var brain=c.GetComponent<Cinemachine.CinemachineBrain>();
 var originalPosition=c.transform.position; var start=c.transform.position; bool wasEnabled=brain.enabled; float scale=UnityEngine.Time.timeScale;
 var water=c.GetComponent<FirstLevelWater>();
 var mat=(UnityEngine.Material)typeof(FirstLevelWater).GetField("material",System.Reflection.BindingFlags.NonPublic|System.Reflection.BindingFlags.Instance).GetValue(water);
 try {
 brain.enabled=false; UnityEngine.Time.timeScale=0; start.y=water.waterHeight+1f; c.transform.position=start;
 yield return null;
 UnityEngine.ScreenCapture.CaptureScreenshot("scripts/water-20261112/ten-layers/still.png");
 for(int i=0;i<90;i++) {
 c.transform.position=start+UnityEngine.Vector3.right*(2f*(i+1)/90f);
 if(i==44) UnityEngine.ScreenCapture.CaptureScreenshot("scripts/water-20261112/ten-layers/move-mid.png");
 if(i==89) UnityEngine.ScreenCapture.CaptureScreenshot("scripts/water-20261112/ten-layers/move-end.png");
 yield return null;
 }
 UnityEngine.Debug.Log("Moving: offset="+mat.GetVector("_CameraOffset")+" travel="+mat.GetFloat("_CameraTravel")+" motion="+mat.GetFloat("_CameraMotion"));
 yield return new UnityEngine.WaitForSecondsRealtime(1.5f);
 UnityEngine.Debug.Log("Stopped: motion="+mat.GetFloat("_CameraMotion"));
 UnityEngine.ScreenCapture.CaptureScreenshot("scripts/water-20261112/ten-layers/settled.png");
 yield return null;
 var shader=UnityEngine.Resources.Load<UnityEngine.Shader>("KingdomWater");
 foreach(var e in UnityEditor.ShaderUtil.GetShaderMessages(shader)) UnityEngine.Debug.Log(e.severity+": "+e.message);
 UnityEngine.Debug.Log("Shader supported="+shader.isSupported);
 } finally {c.transform.position=originalPosition;brain.enabled=wasEnabled;UnityEngine.Time.timeScale=scale;}
} return Check();
